def solve():
    import sys
    u, v = map(int, sys.stdin.readline().split())

    if u == 0 and v == 0:
        print(0)
        return

    if v < u:
        print(-1)
        return

    if u == 0:
        if v % 2 == 0:
            n = v // 2
            print(n)
            print(' '.join(['1'] * n))
        else:
            print(-1)
        return

    if v == u:
        print(1)
        print(u)
        return

    if (v - u) % 2 != 0:
        print(-1)
        return

    diff = (v - u) // 2
    if diff < 0:
        print(-1)
        return

    if u == 0:
        if v % 2 == 0:
            n = v // 2
            print(n)
            print(' '.join(['1'] * n))
        else:
            print(-1)
        return

    if (u & v) != u:
        print(-1)
        return

    if diff == 0:
        print(2)
        print(f"{u} {u}")
        return

    print(3)
    print(f"{u} {diff} {diff}")

solve()
